INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (100101, 8, "トゥインクルウィッシュ", 2, "人助けが大好き！　前向き格闘娘", 155, 44, "人助け、応援", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, "A", "東山奈央", "獣人族", "ヒヨリ", 16, 27);
