INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (101101, 8, "ラビリンス", 3, "人懐っこくてマシンガントークな妹系少女", 156, 44, "お裁縫", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 0, "A", "阿澄佳奈", "ヒューマン", "リノ", 15, 25);
