INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (104901, 10, "ラビリンス", 3, "お姉ちゃんがお世話してあげるからねっ！", 168, 54, "家事全般", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, "O", "生天目仁美", "ヒューマン", "シズル", 18, 24);
