INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (105101, 3, "トワイライトキャラバン", 13, "実験が趣味の危険な科学者", 166, 53, "研究、実験", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 0, "A", "三石琴乃", "ヒューマン", "ミツキ", 27, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (105201, 3, "牧場（エリザベスパーク）", 11, "乙女チックなもふもふアニマル", 150, 100, "毛繕い、お喋り", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 0, "A", "徳井青空", "獣人族", "リマ", 17, 14);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (105301, 7, "ヴァイスフリューゲル　ランドソル支部", 15, "見た目も中身もお子ちゃまな異国の軍人", 140, 33, "お菓子屋通い", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 0, "A", "辻あゆみ", "ヒューマン", "モニカ", 17, 28);
