INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (105701, 3, "？？？", "", "空への冒険を夢見る騎空士の少女", 156, 45, "冒険、おしゃべり", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", 0, "O", "金元寿子", "ヒューマン", "ジータ", 17, 10);
