INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108001, 11, "メルクリウス財団", 12, "仕事も私事も効率優先な傭兵少女", 163, 49, "傭兵などのアルバイト", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, "O", "田所あずさ", "ヒューマン", "ミフユ（サマー）", 20, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108101, 12, "悪魔偽王国軍（ディアボロス）", 7, "占いが得意な霊能少女", 157, 42, "占い", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, "AB", "大坪由佳", "魔族", "シノブ（ハロウィン）", 18, 22);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108201, 1, "悪魔偽王国軍（ディアボロス）", 7, "プリン大好きゴースト娘", 130, 32, "プリンを食べること", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, "B", "雨宮天", "魔族", "ミヤコ（ハロウィン）", 14, 23);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108301, 1, "ルーセント学院", 14, "ちょっとおませな恋に恋する女の子", 120, 22, "ファッション誌鑑賞、コスメ集め", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 0, "A", "久野美咲", "魔族", "ミサキ（ハロウィン）", 11, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108401, 6, "カルミナ", 4, "人々を守るために歌う、唱喚士の少女", 163, 46, "各種楽器", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, "O", "福原綾香", "ヒューマン", "チカ（クリスマス）", 17, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108501, 6, "サレンディア救護院", 9, "泣き虫で臆病な守ってあげたい女の子", 150, 40, "観劇、おままごと", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, "B", "植田佳奈", "ヒューマン", "クルミ（クリスマス）", 12, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108601, 5, "サレンディア救護院", 9, "ぷうきちといつも一緒！", 148, 38, "屋内でできる遊び", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, "B", "芹澤優", "ヒューマン", "アヤネ（クリスマス）", 14, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108701, 8, "トゥインクルウィッシュ", 2, "人助けが大好き！　前向き格闘娘", 155, 44, "人助け、応援", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, "A", "東山奈央", "獣人族", "ヒヨリ（ニューイヤー）", 16, 27);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108801, 4, "トゥインクルウィッシュ", 2, "戦闘のサポートが得意な、心優しい少女", 158, 47, "料理、人間観察", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, "O", "種田梨沙", "ヒューマン", "ユイ（ニューイヤー）", 17, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (108901, 1, "トゥインクルウィッシュ", 2, "クールで何事にも真っ直ぐな剣士", 163, 46, "読書、乗馬、お茶", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, "B", "早見沙織", "魔族", "レイ（ニューイヤー）", 18, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (109001, 7, "トワイライトキャラバン", 13, "運命の相手に一途すぎる乙女", 154, 43, "実験、裁縫、料理", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, "B", "橋本ちなみ", "魔族", "エリコ（バレンタイン）", 16, 30);
