INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (109201, 12, "？？？", "", "英霊と契約を結んだマナリアの天才王女", 156, 55, "読書", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 0, "AB", "日笠陽子", "ヒューマン", "アン", 17, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (109301, 2, "？？？", "", "マナリア魔法学院の新入生", 144, 45, "食べること、眠ること", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 0, "O", "こやまきみこ", "ヒューマン", "ルゥ", 16, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (109401, 11, "？？？", "", "人を超越した力を有す心優しい竜姫", 167, 67, "ピアノ", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 0, "B", "福原綾香", "半人半竜", "グレア", 17, 3);
